// Original ambient score and restrained, event-specific Web Audio sound design.
const PREFS='parallax-audio-v2';
const clamp=v=>Math.max(0,Math.min(1,Number(v)));
export function createSoundscape(){
 let prefs={enabled:true,music:.65,effects:.55};try{const p=JSON.parse(localStorage.getItem(PREFS)||'null');if(p){prefs.enabled=p.enabled!==false;for(const k of ['music','effects'])if(Number.isFinite(p[k]))prefs[k]=clamp(p[k]);}}catch{}
 let ctx,master,musicBus,effectsBus,filter,reverb,wet,analyser,noiseBuffer,musicSource,musicPromise,phase=0,suspendTimer,lastFoot=-1,started=false,musicReady=false,loadFailed=false;
 const button=document.getElementById('sound'),label=document.getElementById('sound-label');
 const panel=document.createElement('div');panel.id='audio-panel';panel.hidden=true;panel.dataset.audioUi='true';panel.setAttribute('role','region');panel.setAttribute('aria-label','Audio settings');panel.innerHTML='<div class="audio-title"><strong>Soundscape</strong><button id="audio-close" aria-label="Close audio settings">×</button></div><p>Room to think. A little atmosphere.</p><label for="music-volume">Music <output id="music-value"></output></label><input id="music-volume" type="range" min="0" max="100" step="1"><label for="effects-volume">Effects <output id="effects-value"></output></label><input id="effects-volume" type="range" min="0" max="100" step="1"><button id="audio-toggle" class="audio-mute"></button><span id="audio-message" role="status"></span>';
 button.parentElement.append(panel);button.dataset.audioUi='true';button.setAttribute('aria-controls','audio-panel');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Audio settings');
 const $=id=>document.getElementById(id);
 function save(){try{localStorage.setItem(PREFS,JSON.stringify(prefs));}catch{}}
 function update(){label.textContent=!prefs.enabled?'Muted':started?'Sound on':'Sound';button.title=prefs.enabled?'Music and effects settings':'Sound is muted';button.classList.toggle('audio-muted',!prefs.enabled);for(const k of ['music','effects']){$(k+'-volume').value=Math.round(prefs[k]*100);$(k+'-value').textContent=Math.round(prefs[k]*100)+'%';}const toggle=$('audio-toggle');toggle.textContent=prefs.enabled?'Mute all sound':'Turn sound on';toggle.setAttribute('aria-pressed',String(!prefs.enabled));$('audio-message').textContent=loadFailed?'Music couldn’t load. Tap Sound to retry.':!prefs.enabled?'Your sound preference is saved.':!started?'Sound begins when you start playing.':!musicReady?'Loading the ambient score…':'Original ambient score · headphones welcome';}
 function ramp(param,value,time=.12){param.cancelScheduledValues(ctx.currentTime);param.setTargetAtTime(value,ctx.currentTime,time);}
 function mix(){if(!ctx)return;ramp(master.gain,prefs.enabled&&!document.hidden?.82:0);ramp(musicBus.gain,prefs.music*(phase?.9:1),.5);ramp(effectsBus.gain,prefs.effects);ramp(filter.frequency,phase?2400:6500,.6);}
 function initialize(){if(ctx)return;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw new Error('Web Audio unavailable');ctx=new Audio();master=ctx.createGain();master.gain.value=0;musicBus=ctx.createGain();musicBus.gain.value=prefs.music;effectsBus=ctx.createGain();effectsBus.gain.value=prefs.effects;filter=ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=6500;filter.Q.value=.35;musicBus.connect(filter).connect(master);effectsBus.connect(master);
 const compressor=ctx.createDynamicsCompressor();compressor.threshold.value=-14;compressor.knee.value=15;compressor.ratio.value=2.5;compressor.attack.value=.015;compressor.release.value=.3;analyser=ctx.createAnalyser();analyser.fftSize=1024;master.connect(compressor).connect(analyser).connect(ctx.destination);
 reverb=ctx.createConvolver();const n=Math.floor(ctx.sampleRate*2.6),impulse=ctx.createBuffer(2,n,ctx.sampleRate);for(let ch=0;ch<2;ch++){const a=impulse.getChannelData(ch);let low=0;for(let i=0;i<n;i++){low=.64*low+.36*(Math.random()*2-1);a[i]=low*Math.pow(1-i/n,3.2)*(i<ctx.sampleRate*.025?0:1);}}reverb.buffer=impulse;wet=ctx.createGain();wet.gain.value=.2;effectsBus.connect(reverb).connect(wet).connect(master);
 noiseBuffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate);const noise=noiseBuffer.getChannelData(0);let brown=0;for(let i=0;i<noise.length;i++){brown=.92*brown+.08*(Math.random()*2-1);noise[i]=brown*3;}
 }
 async function loadMusic(){if(musicSource||musicPromise)return musicPromise;musicPromise=(async()=>{const response=await fetch(new URL('./assets/ambient.mp3',import.meta.url));if(!response.ok)throw new Error('Music unavailable');const buffer=await ctx.decodeAudioData(await response.arrayBuffer());musicSource=ctx.createBufferSource();musicSource.buffer=buffer;musicSource.loop=true;const entrance=ctx.createGain();entrance.gain.setValueAtTime(0,ctx.currentTime);entrance.gain.linearRampToValueAtTime(1,ctx.currentTime+1.5);musicSource.connect(entrance).connect(musicBus);musicSource.start();musicReady=true;loadFailed=false;mix();update();})().catch(()=>{loadFailed=true;update();}).finally(()=>{musicPromise=null;});return musicPromise;}
 async function unlock(){if(!prefs.enabled||document.hidden)return;try{initialize();clearTimeout(suspendTimer);await ctx.resume();started=ctx.state==='running';mix();update();loadMusic();}catch{loadFailed=true;update();}}
 function gesture(e){if(e.type==='keydown'&&(e.metaKey||e.ctrlKey||e.altKey||['Shift','Control','Alt','Meta','Tab','Escape'].includes(e.key)))return;if(!started||ctx?.state!=='running'||loadFailed)unlock();}
 document.addEventListener('pointerdown',gesture,{capture:true,passive:true});document.addEventListener('keydown',gesture,{capture:true});
 function audible(){return prefs.enabled&&ctx?.state==='running'&&prefs.effects>0&&!document.hidden;}
 function voice(frequency,{at=ctx.currentTime,amp=.05,length=1,attack=.012,pan=0,partials=[1,.22,.05]}={}){const g=ctx.createGain(),p=ctx.createStereoPanner(),cut=ctx.createBiquadFilter();g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(amp,at+attack);g.gain.exponentialRampToValueAtTime(.00001,at+length);cut.type='lowpass';cut.frequency.value=3800;p.pan.value=pan;g.connect(cut).connect(p).connect(effectsBus);let ended=0;partials.forEach((level,i)=>{const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=frequency*[1,2.003,3.997][i];gain.gain.value=level;osc.connect(gain).connect(g);osc.start(at);osc.stop(at+length+.03);osc.onended=()=>{osc.disconnect();gain.disconnect();if(++ended===partials.length){g.disconnect();cut.disconnect();p.disconnect();}};});}
 function air({at=ctx.currentTime,length=.2,amp=.04,low=250,high=900,pan=0,attack=.015}={}){const source=ctx.createBufferSource(),f=ctx.createBiquadFilter(),g=ctx.createGain(),p=ctx.createStereoPanner();source.buffer=noiseBuffer;f.type='bandpass';f.Q.value=.6;f.frequency.setValueAtTime(low,at);f.frequency.exponentialRampToValueAtTime(high,at+length*.45);f.frequency.exponentialRampToValueAtTime(low,at+length);g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(amp,at+attack);g.gain.exponentialRampToValueAtTime(.00001,at+length);p.pan.value=pan;source.connect(f).connect(g).connect(p).connect(effectsBus);source.start(at,Math.random()*.4);source.stop(at+length+.02);source.onended=()=>[source,f,g,p].forEach(n=>n.disconnect());}
 function step(tile){if(!audible()||ctx.currentTime-lastFoot<.11)return;lastFoot=ctx.currentTime;const pan=(Math.random()-.5)*.3;air({length:.13,amp:.065,low:tile==='B'?500:240,high:tile==='B'?1800:700,pan,attack:.004});voice(tile==='B'?156:104,{amp:.028,length:.11,attack:.005,pan,partials:[1,.06]});}
 function shift(next){phase=next;mix();if(!audible())return;air({length:1.15,amp:.12,low:next?240:400,high:next?1150:2000,pan:next?.18:-.18,attack:.3});voice(next?146.83:220,{amp:.04,length:2.1,attack:.24,partials:[1,.14]});}
 function collect(count){if(!audible())return;const at=ctx.currentTime,notes=[587.33,659.25,739.99],f=notes[(count-1)%3];voice(f,{at,amp:.09,length:2.2,attack:.014,pan:-.16});voice(f*1.5,{at:at+.12,amp:.03,length:1.8,attack:.025,pan:.23,partials:[1,.12]});}
 function fall(){if(!audible())return;air({length:.55,amp:.1,low:150,high:400,attack:.12});voice(146.83,{amp:.03,length:.65,attack:.06,partials:[1]});}
 function complete(){if(!audible())return;const at=ctx.currentTime;[293.66,440,554.37,659.25].forEach((f,i)=>voice(f,{at:at+i*.2,amp:.06,length:3.6,attack:.045,pan:(i-1.5)*.13,partials:[1,.12,.03]}));}
 button.onclick=()=>{panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden));if(prefs.enabled)unlock();};$('audio-close').onclick=()=>{panel.hidden=true;button.setAttribute('aria-expanded','false');button.focus();};document.addEventListener('pointerdown',e=>{if(!panel.hidden&&!panel.contains(e.target)&&!button.contains(e.target)){panel.hidden=true;button.setAttribute('aria-expanded','false');}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){panel.hidden=true;button.setAttribute('aria-expanded','false');button.focus();}});
 for(const k of ['music','effects'])$(k+'-volume').addEventListener('input',e=>{prefs[k]=clamp(Number(e.target.value)/100);save();mix();update();});$('audio-toggle').onclick=()=>{prefs.enabled=!prefs.enabled;save();if(prefs.enabled)unlock();else if(ctx){mix();clearTimeout(suspendTimer);suspendTimer=setTimeout(()=>{if(!prefs.enabled)ctx.suspend();},450);}update();};
 document.addEventListener('visibilitychange',()=>{if(!ctx)return;clearTimeout(suspendTimer);if(document.hidden){mix();suspendTimer=setTimeout(()=>{if(document.hidden)ctx.suspend();},450);}else if(prefs.enabled)unlock();});
 update();return {step,shift,collect,fall,complete,setPerspective(next){phase=next;mix();},inspect(){let rms=0;if(analyser&&ctx.state==='running'){const samples=new Float32Array(analyser.fftSize);analyser.getFloatTimeDomainData(samples);rms=Math.sqrt(samples.reduce((sum,v)=>sum+v*v,0)/samples.length);}return{enabled:prefs.enabled,context:ctx?.state||'not_started',musicReady,musicPlaying:!!musicSource&&ctx?.state==='running'&&prefs.enabled,musicVolume:prefs.music,effectsVolume:prefs.effects,rms,loadFailed};}};
}
